#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "adi.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// First apply j_vec (inner), then i_vec (outer) to match C layout u[i][j]
	DEFINE_PROTO_STRUCT(u_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(v_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(p_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(q_layout, j_vec ^ i_vec);
} tuning;


// initialization function
void init_array(auto U) {
	using namespace noarr;

	auto n = U | get_length<'i'>();

	// U: i x j
	noarr::traverser(U).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		U[state] = (num_t)(i + n - j) / (num_t)n;
	});
}


// computation kernel
//
// Optimizations over the original:
//  - Keep data‑parallel sweeps over 'i' but express them via traverser ranges,
//    then parallelize the outer 'i' loops with OpenMP.
//  - Keep per‑column / per‑row dependency along 'j' strictly sequential
//    by using traversers that iterate only 'j' in increasing order, and
//    implement backward sweeps via an index transform (k -> j = n-1-k).
//  - Precompute constants that were recomputed inside inner loops
//    (e.g. 1+2*d, 1+2*a) to reduce arithmetic overhead.
//  - Reuse sliced proto‑structures for inner regions (1 .. n-2) in both
//    column and row sweeps.
//
[[gnu::flatten, gnu::noinline]]
void kernel_adi(std::size_t tsteps, auto U, auto V, auto P, auto Q) {
	using namespace noarr;

	const auto n = U | get_length<'i'>();

#pragma scop

	// Constant coefficients of the ADI scheme
	const num_t DX   = SCALAR_VAL(1.0) / (num_t)n;
	const num_t DY   = SCALAR_VAL(1.0) / (num_t)n;
	const num_t DT   = SCALAR_VAL(1.0) / (num_t)tsteps;
	const num_t B1   = SCALAR_VAL(2.0);
	const num_t B2   = SCALAR_VAL(1.0);
	const num_t mul1 = B1 * DT / (DX * DX);
	const num_t mul2 = B2 * DT / (DY * DY);

	const num_t a = -mul1 / SCALAR_VAL(2.0);
	const num_t b = SCALAR_VAL(1.0) + mul1;
	const num_t c = a;
	const num_t d = -mul2 / SCALAR_VAL(2.0);
	const num_t e = SCALAR_VAL(1.0) + mul2;
	const num_t f = d;

	const num_t one = SCALAR_VAL(1.0);
	const num_t two = SCALAR_VAL(2.0);

	// These are used in every inner‑loop iteration; precompute once
	const num_t one_plus_2d = one + two * d;
	const num_t one_plus_2a = one + two * a;

	// Common proto‑structures for the interior region: i,j in [1, n-2]
	const auto slice_i_inner = noarr::slice<'i'>(1, n - 2);
	const auto slice_j_inner = noarr::slice<'j'>(1, n - 2);

	// One‑step shift in 'j' (used for accessing j-1 via state arithmetic)
	const auto step_prev_j = noarr::idx<'j'>(1);

	for (std::size_t t = 1; t <= tsteps; ++t) {

		// -----------------------------------------------------------------
		// Column sweep: for each fixed i, solve along j.
		// The work over different i is independent and parallelizable.
		// -----------------------------------------------------------------

		auto col_range = noarr::traverser(U, V, P, Q).order(slice_i_inner).range();
		const std::size_t col_count = col_range.size();

		#pragma omp parallel for schedule(static)
		for (long long idx = 0; idx < static_cast<long long>(col_count); ++idx) {
			auto trav_i = col_range[static_cast<std::size_t>(idx)];

			// 'trav_i' has dimension 'i' fixed; only 'j' remains
			auto state_i = trav_i.state();
			const std::size_t i = noarr::get_index<'i'>(state_i);

			// Boundary conditions for column i
			V[noarr::idx<'i', 'j'>(0, i)] = one;
			P[noarr::idx<'i', 'j'>(i, 0)] = SCALAR_VAL(0.0);
			Q[noarr::idx<'i', 'j'>(i, 0)] = V[noarr::idx<'i', 'j'>(0, i)];

			// Forward sweep in j: j = 1 .. n-2
			auto trav_ij_fwd = trav_i.order(slice_j_inner);
			trav_ij_fwd.for_each([&](auto state) {
				const auto prev = state - step_prev_j; // (i, j-1)
				const std::size_t j = noarr::get_index<'j'>(state);

				const num_t denom = a * P[prev] + b;
				P[state] = -c / denom;

				// Note: original Polybench kernel uses u[j-1][i], u[j][i], u[j+1][i]
				const num_t u_j_im1 = U[noarr::idx<'i', 'j'>(j, i - 1)];
				const num_t u_j_i   = U[noarr::idx<'i', 'j'>(j, i    )];
				const num_t u_j_ip1 = U[noarr::idx<'i', 'j'>(j, i + 1)];

				Q[state] = (-d * u_j_im1
				            + one_plus_2d * u_j_i
				            - f * u_j_ip1
				            - a * Q[prev]) / denom;
			});

			// Boundary at bottom row of column i
			V[noarr::idx<'i', 'j'>(n - 1, i)] = one;

			// Backward sweep in j: j = n-2 .. 1
			// Implemented as forward sweep over auxiliary index k = 1 .. n-2
			// with mapping j = n-1-k, so iteration order is preserved for
			// dependencies along j, while still using a simple traverser.
			auto trav_ij_bwd = trav_i.order(slice_j_inner);
			trav_ij_bwd.for_each([&](auto state) {
				const std::size_t k = noarr::get_index<'j'>(state);
				const std::size_t j = n - 1 - k; // n-2, n-3, ..., 1

				const auto pij_state   = noarr::idx<'i', 'j'>(i, j);
				const auto vjp1i_state = noarr::idx<'i', 'j'>(j + 1, i);

				V[noarr::idx<'i', 'j'>(j, i)] =
					P[pij_state] * V[vjp1i_state] + Q[pij_state];
			});
		}

		// -----------------------------------------------------------------
		// Row sweep: for each fixed i, solve along j (now using V).
		// Again, rows (different i) are independent and parallelizable.
		// -----------------------------------------------------------------

		auto row_range = noarr::traverser(U, V, P, Q).order(slice_i_inner).range();
		const std::size_t row_count = row_range.size();

		#pragma omp parallel for schedule(static)
		for (long long idx = 0; idx < static_cast<long long>(row_count); ++idx) {
			auto trav_i = row_range[static_cast<std::size_t>(idx)];

			auto state_i = trav_i.state();
			const std::size_t i = noarr::get_index<'i'>(state_i);

			// Boundary conditions for row i
			U[noarr::idx<'i', 'j'>(i, 0)] = one;
			P[noarr::idx<'i', 'j'>(i, 0)] = SCALAR_VAL(0.0);
			Q[noarr::idx<'i', 'j'>(i, 0)] = U[noarr::idx<'i', 'j'>(i, 0)];

			// Forward sweep in j: j = 1 .. n-2
			auto trav_ij_fwd = trav_i.order(slice_j_inner);
			trav_ij_fwd.for_each([&](auto state) {
				const auto prev = state - step_prev_j; // (i, j-1)
				const std::size_t j = noarr::get_index<'j'>(state);

				const num_t denom = d * P[prev] + e;
				P[state] = -f / denom;

				const num_t v_im1_j = V[noarr::idx<'i', 'j'>(i - 1, j)];
				const num_t v_i_j   = V[noarr::idx<'i', 'j'>(i    , j)];
				const num_t v_ip1_j = V[noarr::idx<'i', 'j'>(i + 1, j)];

				Q[state] = (-a * v_im1_j
				            + one_plus_2a * v_i_j
				            - c * v_ip1_j
				            - d * Q[prev]) / denom;
			});

			// Boundary at rightmost column of row i
			U[noarr::idx<'i', 'j'>(i, n - 1)] = one;

			// Backward sweep in j: j = n-2 .. 1
			auto trav_ij_bwd = trav_i.order(slice_j_inner);
			trav_ij_bwd.for_each([&](auto state) {
				const std::size_t k = noarr::get_index<'j'>(state);
				const std::size_t j = n - 1 - k; // n-2, ..., 1

				const auto pij_state   = noarr::idx<'i', 'j'>(i, j);
				const auto uijp1_state = noarr::idx<'i', 'j'>(i, j + 1);

				U[pij_state] = P[pij_state] * U[uijp1_state] + Q[pij_state];
			});
		}
	}

#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// input data
	auto set_lengths = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);

	auto U = noarr::bag(noarr::scalar<num_t>() ^ tuning.u_layout ^ set_lengths);
	auto V = noarr::bag(noarr::scalar<num_t>() ^ tuning.v_layout ^ set_lengths);
	auto P = noarr::bag(noarr::scalar<num_t>() ^ tuning.p_layout ^ set_lengths);
	auto Q = noarr::bag(noarr::scalar<num_t>() ^ tuning.q_layout ^ set_lengths);

	// initialize data
	init_array(U.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_adi(tsteps, U.get_ref(), V.get_ref(), P.get_ref(), Q.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, U.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
