	});
}


// computation kernel
//  - keeps the original ADI scheme
//  - reduces memory traffic by keeping recurrent P/Q and V/U values in registers
//  - precomputes frequently used constants and slicing proto-structures
[[gnu::flatten, gnu::noinline]]
void kernel_adi(std::size_t tsteps, auto U, auto V, auto P, auto Q) {
	using namespace noarr;

	const auto n = U | get_length<'i'>();

	// Precompute scalar constants once, outside the time loop
	const num_t one = SCALAR_VAL(1.0);
	const num_t two = SCALAR_VAL(2.0);

	const num_t DX = one / (num_t)n;
	const num_t DY = one / (num_t)n;
	const num_t DT = one / (num_t)tsteps;
	const num_t B1 = two;
	const num_t B2 = one;
	const num_t mul1 = B1 * DT / (DX * DX);
	const num_t mul2 = B2 * DT / (DY * DY);

	const num_t a = -mul1 / two;
	const num_t b = one + mul1;
	const num_t c = a;
	const num_t d = -mul2 / two;
	const num_t e = one + mul2;
	const num_t f = d;

	// Coefficients that appear inside inner loops, hoisted once
	const num_t col_center_coeff = one + two * d; // (1 + 2*d)
	const num_t row_center_coeff = one + two * a; // (1 + 2*a)

	// Common proto-structures describing the interior (1 .. n-2) in each dimension
	const auto interior_i = noarr::slice<'i'>(1, n - 2);
	const auto interior_j = noarr::slice<'j'>(1, n - 2);

#pragma scop
	for (std::size_t t = 1; t <= tsteps; t++) {

		// ---------------------------------------------------------------------
		// Column sweep
		// ---------------------------------------------------------------------
		// For each fixed original "i" index we solve a tridiagonal system along
		// "j". Dependencies are along j only, so each column is independent.

		noarr::traverser(U, V, P, Q)
			.order(interior_i) // restrict i to 1 .. n-2
			.template for_dims<'i'>([&](auto trav_i) {
				const auto istate = trav_i.state();
				const std::size_t i = get_index<'i'>(istate);

				// Boundary conditions for column i
				V[noarr::idx<'i', 'j'>(0,     i)] = one;
				P[noarr::idx<'i', 'j'>(i,     0)] = SCALAR_VAL(0.0);
				Q[noarr::idx<'i', 'j'>(i,     0)] = V[noarr::idx<'i', 'j'>(0, i)];

				// Forward sweep in j: j = 1 .. n-2
				// Keep P[i][j-1] and Q[i][j-1] in registers to avoid
				// repeatedly loading them from memory.
				num_t P_prev = P[noarr::idx<'i', 'j'>(i, 0)];
				num_t Q_prev = Q[noarr::idx<'i', 'j'>(i, 0)];

				trav_i.order(interior_j).for_each([&](auto state) {
					const std::size_t j = get_index<'j'>(state);

					const num_t denom = a * P_prev + b;
					const num_t P_cur = -c / denom;

					const num_t u_j_im1 = U[noarr::idx<'i', 'j'>(j, i - 1)];
					const num_t u_j_i   = U[noarr::idx<'i', 'j'>(j, i    )];
					const num_t u_j_ip1 = U[noarr::idx<'i', 'j'>(j, i + 1)];

					const num_t Q_cur =
						(-d * u_j_im1
						 + col_center_coeff * u_j_i
						 - f * u_j_ip1
						 - a * Q_prev) / denom;

					P[state] = P_cur;
  					Q[state] = Q_cur;

					P_prev = P_cur;
					Q_prev = Q_cur;
				});

				// Boundary at bottom row
				V[noarr::idx<'i', 'j'>(n - 1, i)] = one;

				// Backward sweep in j: j = n-2 .. 1
				// Original recurrence:
				//   V[j][i] = P[i][j] * V[j+1][i] + Q[i][j]
				// We track V[j+1][i] in a scalar v_next instead of
				// reloading it from memory in every iteration.
				num_t v_next = V[noarr::idx<'i', 'j'>(n - 1, i)]; // V[n-1][i]

				trav_i.order(interior_j).for_each([&](auto state) {
					const std::size_t k = get_index<'j'>(state); // 1 .. n-2
					const std::size_t j = n - 1 - k;             // n-2 .. 1

					const auto pij_state = noarr::idx<'i', 'j'>(i, j);

					const num_t v_cur = P[pij_state] * v_next + Q[pij_state];
					V[noarr::idx<'i', 'j'>(j, i)] = v_cur;

					v_next = v_cur; // for the next (smaller) j
				});
			});

		// ---------------------------------------------------------------------
		// Row sweep
		// ---------------------------------------------------------------------
		// Symmetric to the column sweep, but along the other spatial
		// direction and using V as input and U as output.

		noarr::traverser(U, V, P, Q)
			.order(interior_i) // i = 1 .. n-2
			.template for_dims<'i'>([&](auto trav_i) {
				const auto istate = trav_i.state();
				const std::size_t i = get_index<'i'>(istate);

				// Boundary conditions for row i
				U[noarr::idx<'i', 'j'>(i, 0)] = one;
				P[noarr::idx<'i', 'j'>(i, 0)] = SCALAR_VAL(0.0);
				Q[noarr::idx<'i', 'j'>(i, 0)] = U[noarr::idx<'i', 'j'>(i, 0)];

				// Forward sweep in j: j = 1 .. n-2
				num_t P_prev = P[noarr::idx<'i', 'j'>(i, 0)];
				num_t Q_prev = Q[noarr::idx<'i', 'j'>(i, 0)];

				trav_i.order(interior_j).for_each([&](auto state) {
					const std::size_t j = get_index<'j'>(state);

					const num_t denom = d * P_prev + e;
					const num_t P_cur = -f / denom;

					const num_t v_im1_j = V[noarr::idx<'i', 'j'>(i - 1, j)];
					const num_t v_i_j   = V[noarr::idx<'i', 'j'>(i,     j)];
					const num_t v_ip1_j = V[noarr::idx<'i', 'j'>(i + 1, j)];

					const num_t Q_cur =
						(-a * v_im1_j
						 + row_center_coeff * v_i_j
						 - c * v_ip1_j
						 - d * Q_prev) / denom;

					P[state] = P_cur;
					Q[state] = Q_cur;

					P_prev = P_cur;
					Q_prev = Q_cur;
				});

				// Boundary at rightmost column
				U[noarr::idx<'i', 'j'>(i, n - 1)] = one;

				// Backward sweep in j: j = n-2 .. 1
				//   U[i][j] = P[i][j] * U[i][j+1] + Q[i][j]
				// Track U[i][j+1] in u_next to avoid redundant loads.
				num_t u_next = U[noarr::idx<'i', 'j'>(i, n - 1)]; // U[i][n-1]

				trav_i.order(interior_j).for_each([&](auto state) {
					const std::size_t k = get_index<'j'>(state); // 1 .. n-2
					const std::size_t j = n - 1 - k;             // n-2 .. 1

					const auto pij_state = noarr::idx<'i', 'j'>(i, j);

					const num_t u_cur = P[pij_state] * u_next + Q[pij_state];
					U[pij_state] = u_cur;

					u_next = u_cur; // for the next (smaller) j
				});
			});
	}
#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// input data
	auto set_lengths = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);

	auto U = noarr::bag(noarr::scalar<num_t>() ^ tuning.u_layout ^ set_lengths);
	auto V = noarr::bag(noarr::scalar<num_t>() ^ tuning.v_layout ^ set_lengths);
	auto P = noarr::bag(noarr::scalar<num_t>() ^ tuning.p_layout ^ set_lengths);
	auto Q = noarr::bag(noarr::scalar<num_t>() ^ tuning.q_layout ^ set_lengths);

	// initialize data
	init_array(U.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_adi(tsteps, U.get_ref(), V.get_ref(), P.get_ref(), Q.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, U.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
