// computation kernel
//
// Optimizations compared to the original version:
//  - coefficients (DX, DY, DT, a..f) and frequently used combinations are
//    computed once and kept const
//  - in the Thomas sweeps, we compute 1/denom once per grid point and reuse it
//    for both P and Q updates (one division instead of two)
//  - explicit constants for 1.0 and 0.0 avoid repeated SCALAR_VAL calls
//  - traversal over the 'i' dimension is parallelized with OpenMP using
//    range-based loops over Noarr traversers; if compiled without OpenMP,
//    pragmas are ignored and the code runs serially
//  - sliced views for interior points in 'i' and 'j' are created once and
//    reused in all time steps
[[gnu::flatten, gnu::noinline]]
void kernel_adi(std::size_t tsteps, auto U, auto V, auto P, auto Q) {
	using namespace noarr;

	const std::size_t n = U | get_length<'i'>();

	// ---------------------------------------------------------------------
	// Precompute scalar coefficients (identical for all time steps)
	// ---------------------------------------------------------------------
	const num_t DX   = SCALAR_VAL(1.0) / (num_t)n;
	const num_t DY   = SCALAR_VAL(1.0) / (num_t)n;
	const num_t DT   = SCALAR_VAL(1.0) / (num_t)tsteps;
	const num_t B1   = SCALAR_VAL(2.0);
	const num_t B2   = SCALAR_VAL(1.0);
	const num_t mul1 = B1 * DT / (DX * DX);
	const num_t mul2 = B2 * DT / (DY * DY);

	const num_t a = -mul1 / SCALAR_VAL(2.0);
	const num_t b = SCALAR_VAL(1.0) + mul1;
	const num_t c = a;
	const num_t d = -mul2 / SCALAR_VAL(2.0);
	const num_t e = SCALAR_VAL(1.0) + mul2;
	const num_t f = d;

	const num_t one  = SCALAR_VAL(1.0);
	const num_t zero = SCALAR_VAL(0.0);

	// Frequently used linear combinations
	const num_t one_plus_two_d = one + SCALAR_VAL(2.0) * d;
	const num_t one_plus_two_a = one + SCALAR_VAL(2.0) * a;

