	for (std::size_t t = 1; t <= tsteps; t++) {

		// ==============================================================
		// Column sweep: compute V from U, using P and Q as temporaries
		// ==============================================================
		//
		// We traverse the interior in 'i' (i = 1 .. n-2), each iteration
		// of the outer loop receives a traverser with 'i' fixed and 'j'
		// free. The 'i'-loops are parallelized with OpenMP.
		auto col_trav = noarr::traverser(U, V, P, Q).order(interior_i);

#pragma omp parallel for schedule(static)
		for (auto trav_i : col_trav) {
			auto state_i = trav_i.state();
			const std::size_t i = noarr::get_index<'i'>(state_i);

			// Boundary conditions for column i: j = 0 and j = n-1
			V[noarr::idx<'i', 'j'>(0,     i)] = one;
			P[noarr::idx<'i', 'j'>(i,     0)] = zero;
			Q[noarr::idx<'i', 'j'>(i,     0)] = V[noarr::idx<'i', 'j'>(0, i)];

