				const num_t inv_denom = one / denom;   // reuse for P and Q

				P[state] = -c * inv_denom;

				const std::size_t j = noarr::get_index<'j'>(state);

				const num_t u_j_im1 = U[noarr::idx<'i', 'j'>(j, i - 1)];
				const num_t u_j_i   = U[noarr::idx<'i', 'j'>(j, i)];
				const num_t u_j_ip1 = U[noarr::idx<'i', 'j'>(j, i + 1)];

				const num_t rhs =
					-d * u_j_im1 +
					one_plus_two_d * u_j_i +
					-f * u_j_ip1 -
					a * Q[prev];

				Q[state] = rhs * inv_denom;
			});

			// Boundary at bottom row j = n-1
			V[noarr::idx<'i', 'j'>(n - 1, i)] = one;

			// Backward sweep in j: j = n-2 .. 1
			//
			// Implemented as a forward sweep over k = 1 .. n-2 with j = n-1-k,
			// which preserves data layout friendliness (j still traverses the
			// interior slice in the natural order).
			trav_i.order(interior_j).for_each([&](auto state) {
				const std::size_t k = noarr::get_index<'j'>(state);
				const std::size_t j = n - 1 - k; // j = n-2, ..., 1

				const auto pij_state   = noarr::idx<'i', 'j'>(i, j);
				const auto vjp1i_state = noarr::idx<'i', 'j'>(j + 1, i);

				V[noarr::idx<'i', 'j'>(j, i)] =
					P[pij_state] * V[vjp1i_state] + Q[pij_state];
			});
		}

		// ==============================================================
		// Row sweep: compute U from V, using P and Q as temporaries
		// ==============================================================
		//
		// Same pattern, but now the tridiagonal systems are along rows.
		auto row_trav = noarr::traverser(U, V, P, Q).order(interior_i);

#pragma omp parallel for schedule(static)
		for (auto trav_i : row_trav) {
			auto state_i = trav_i.state();
			const std::size_t i = noarr::get_index<'i'>(state_i);

			// Boundary conditions for row i: j = 0 and j = n-1
			U[noarr::idx<'i', 'j'>(i, 0    )] = one;
			P[noarr::idx<'i', 'j'>(i, 0    )] = zero;
			Q[noarr::idx<'i', 'j'>(i, 0    )] = U[noarr::idx<'i', 'j'>(i, 0)];

			// Forward sweep in j: j = 1 .. n-2
			trav_i.order(interior_j).for_each([&](auto state) {
				auto prev = state - noarr::idx<'j'>(1); // j-1 at same i

				const num_t denom     = d * P[prev] + e;
				const num_t inv_denom = one / denom;

				P[state] = -f * inv_denom;

				const std::size_t j = noarr::get_index<'j'>(state);

				const num_t v_im1_j = V[noarr::idx<'i', 'j'>(i - 1, j)];
				const num_t v_i_j   = V[noarr::idx<'i', 'j'>(i,     j)];
				const num_t v_ip1_j = V[noarr::idx<'i', 'j'>(i + 1, j)];

				const num_t rhs =
					-a * v_im1_j +
					one_plus_two_a * v_i_j +
					-c * v_ip1_j -
					d * Q[prev];

				Q[state] = rhs * inv_denom;
			});

			// Boundary at rightmost column j = n-1
			U[noarr::idx<'i', 'j'>(i, n - 1)] = one;

			// Backward sweep in j: j = n-2 .. 1
			trav_i.order(interior_j).for_each([&](auto state) {
				const std::size_t k = noarr::get_index<'j'>(state);
				const std::size_t j = n - 1 - k; // j = n-2, ..., 1

				const auto pij_state   = noarr::idx<'i', 'j'>(i, j);
				const auto uijp1_state = noarr::idx<'i', 'j'>(i, j + 1);

				U[pij_state] = P[pij_state] * U[uijp1_state] + Q[pij_state];
			});
		}
	}
#pragma endscop
