	const num_t diag_d = SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * d; // 1 + 2*d
	const num_t diag_a = SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * a; // 1 + 2*a

