	// them in every inner loop. These only describe index ranges, not data.
	const auto interior_i = noarr::slice<'i'>(1, n - 2); // i = 1 .. n-2
	const auto interior_j = noarr::slice<'j'>(1, n - 2); // j = 1 .. n-2

