	// Traverser stores references only; the numeric values in U,V,P,Q may change
	// between time steps but the geometry of the traversal does not.
	auto base_trav_i = traverser(U, V, P, Q).order(interior_i);

#pragma scop

	for (std::size_t t = 1; t <= tsteps; t++) {

		// ------------------------------------------------------------------
		// Column sweep (implicit solve along the "j" direction for each i)
		// ------------------------------------------------------------------
		//
		// Each i in [1, n-2] is completely independent in this phase:
		// - U is only read
		// - V, P, Q are written only at that i
		// Therefore we can safely parallelize over i with OpenMP.
		//
		// The work inside each iteration is still expressed entirely using
		// Noarr traversers and index states.
		// ------------------------------------------------------------------
#ifdef _OPENMP
#pragma omp parallel for schedule(static)
#endif
		for (auto trav_i : base_trav_i) {
			// trav_i has dimension 'i' fixed and traverses over 'j'
			auto state_i = trav_i.state();
			auto i = get_index<'i'>(state_i); // original global i (1 .. n-2)

			// Boundary conditions for column i
