//  - improved cache locality by reusing traversal descriptors
//  - parallelism over independent lines using OpenMP and traverser ranges
[[gnu::flatten, gnu::noinline]]
void kernel_adi(std::size_t tsteps, auto U, auto V, auto P, auto Q) {
