			// Implemented as a forward sweep over k = 1 .. n-2 with j = n-1-k
			trav_i_j.for_each([=](auto state) {
				auto k = get_index<'j'>(state);      // k = 1 .. n-2
				std::size_t j = n - 1 - k;           // j = n-2, n-3, ..., 1

